mapper.select:
SELECT x.block_idx, x.user_idx, u.user_id, u.nickname, u.user_email, x.block_type, x.blocked_ip, x.is_active AS active, x.reason, x.blocked_by_user_idx, bu.nickname AS blocked_by_nickname, x.released_by_user_idx, ru.nickname AS released_by_nickname, x.blocked_at, x.released_at, x.expires_at, x.block_request_id, x.block_target_key, x.snapshot_status, x.last_history_at, x.synced_at, h.block_scope, h.ip_match_type FROM USER_BLOCKLIST x LEFT JOIN USERS u ON u.user_idx = x.user_idx LEFT JOIN USERS bu ON bu.user_idx = x.blocked_by_user_idx LEFT JOIN USERS ru ON ru.user_idx = x.released_by_user_idx LEFT JOIN USER_BLOCK_HISTORY h ON h.block_idx = x.source_history_block_idx WHERE 1=1
AND x.is_active = 1 AND x.is_active = 0
AND COALESCE(h.block_scope, 'USER_ACTION') = #{scope}
AND x.block_type = #{blockType}
AND h.ip_block_batch_idx = #{batchId}
AND ( u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.user_email LIKE CONCAT('%', #{keyword}, '%') OR x.blocked_ip LIKE CONCAT('%', #{keyword}, '%') OR x.reason LIKE CONCAT('%', #{keyword}, '%') OR x.block_target_key LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY x.is_active DESC, x.blocked_at DESC, x.block_idx DESC LIMIT #{limit}

SELECT ip.ip_blocklist_idx, ip.ip_address, ip.block_request_id, ip.source_history_block_idx, ip.source_blocklist_idx, ip.block_target_key, ip.match_type, ip.cidr_notation, ip.range_start_ip, ip.range_end_ip, ip.country_code, ip.asn, ip.source_scope, ip.block_category, ip.user_idx, ip.block_type, ip.blocked_by_user_idx, bu.nickname AS blocked_by_nickname, ip.reason, ip.is_active AS active, ip.blocked_at, ip.expires_at, ip.released_at, ip.released_by_user_idx, ru.nickname AS released_by_nickname, ip.risk_score, ip.is_auto_block AS auto_block, ip.auto_block_source, ip.detail_message, ip.priority, ip.ip_block_batch_idx, b.batch_code, b.batch_name, COALESCE(b.is_active, 1) AS batch_active, CASE WHEN ip.is_active = 0 THEN 'RULE_INACTIVE' WHEN ip.expires_at IS NOT NULL AND ip.expires_at <= NOW() THEN 'EXPIRED' WHEN ip.ip_block_batch_idx IS NOT NULL AND COALESCE(b.is_active, 0) = 0 THEN 'BATCH_INACTIVE' ELSE 'APPLIED' END AS effective_status FROM IP_BLOCKLIST ip LEFT JOIN USERS bu ON bu.user_idx = ip.blocked_by_user_idx LEFT JOIN USERS ru ON ru.user_idx = ip.released_by_user_idx LEFT JOIN IP_BLOCK_BATCH b ON b.ip_block_batch_idx = ip.ip_block_batch_idx WHERE 1=1
AND ip.is_active = 1 AND ip.is_active = 0
AND ip.source_scope = #{scope}
AND ip.match_type = #{matchType}
AND ip.block_type = #{blockType}
AND ip.block_category = #{category}
AND ip.ip_block_batch_idx = #{batchId}
AND ip.is_active = 1 AND (ip.expires_at IS NULL OR ip.expires_at > NOW()) AND (ip.ip_block_batch_idx IS NULL OR COALESCE(b.is_active, 0) = 1)
AND ip.is_active = 0
AND ip.is_active = 1 AND (ip.expires_at IS NULL OR ip.expires_at > NOW()) AND ip.ip_block_batch_idx IS NOT NULL AND COALESCE(b.is_active, 0) = 0
AND ip.is_active = 1 AND ip.expires_at IS NOT NULL AND ip.expires_at <= NOW()
AND ( ip.ip_address LIKE CONCAT('%', #{keyword}, '%') OR ip.block_target_key LIKE CONCAT('%', #{keyword}, '%') OR ip.cidr_notation LIKE CONCAT('%', #{keyword}, '%') OR ip.range_start_ip LIKE CONCAT('%', #{keyword}, '%') OR ip.range_end_ip LIKE CONCAT('%', #{keyword}, '%') OR ip.country_code LIKE CONCAT('%', #{keyword}, '%') OR ip.asn LIKE CONCAT('%', #{keyword}, '%') OR ip.reason LIKE CONCAT('%', #{keyword}, '%') OR b.batch_name LIKE CONCAT('%', #{keyword}, '%') OR b.batch_code LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY ip.is_active DESC, ip.priority DESC, ip.updated_at DESC, ip.ip_blocklist_idx DESC LIMIT #{limit}

SELECT h.block_idx, h.user_idx, u.user_id, u.nickname, h.block_type, h.blocked_ip, h.is_active AS active, h.reason, h.blocked_by_user_idx, bu.nickname AS blocked_by_nickname, h.released_by_user_idx, ru.nickname AS released_by_nickname, h.blocked_at, h.released_at, h.expires_at, h.block_request_id, h.block_target_key, h.history_kind, h.block_scope, h.ip_match_type, h.cidr_notation, h.range_start_ip, h.range_end_ip, h.ip_block_batch_idx, b.batch_code, b.batch_name, h.list_synced_at FROM USER_BLOCK_HISTORY h LEFT JOIN USERS u ON u.user_idx = h.user_idx LEFT JOIN USERS bu ON bu.user_idx = h.blocked_by_user_idx LEFT JOIN USERS ru ON ru.user_idx = h.released_by_user_idx LEFT JOIN IP_BLOCK_BATCH b ON b.ip_block_batch_idx = h.ip_block_batch_idx WHERE 1=1
AND h.block_scope = #{scope}
AND COALESCE(h.ip_match_type, 'SINGLE_IP') = #{matchType}
AND h.block_type = #{blockType}
AND h.ip_block_batch_idx = #{batchId}
AND ( u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR h.blocked_ip LIKE CONCAT('%', #{keyword}, '%') OR h.reason LIKE CONCAT('%', #{keyword}, '%') OR h.block_target_key LIKE CONCAT('%', #{keyword}, '%') OR h.cidr_notation LIKE CONCAT('%', #{keyword}, '%') OR h.range_start_ip LIKE CONCAT('%', #{keyword}, '%') OR h.range_end_ip LIKE CONCAT('%', #{keyword}, '%') OR b.batch_name LIKE CONCAT('%', #{keyword}, '%') OR b.batch_code LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY h.blocked_at DESC, h.block_idx DESC LIMIT #{limit}

SELECT b.ip_block_batch_idx, b.batch_code, b.batch_name, b.source_type, b.source_name, b.is_active AS active, b.description, b.created_by_user_idx, cu.nickname AS created_by_nickname, b.updated_by_user_idx, uu.nickname AS updated_by_nickname, b.created_at, b.updated_at, (SELECT COUNT(*) FROM IP_BLOCKLIST ip WHERE ip.ip_block_batch_idx = b.ip_block_batch_idx) AS total_rule_count, (SELECT COUNT(*) FROM IP_BLOCKLIST ip WHERE ip.ip_block_batch_idx = b.ip_block_batch_idx AND ip.is_active = 1) AS active_rule_count, (SELECT COUNT(*) FROM IP_BLOCKLIST ip WHERE ip.ip_block_batch_idx = b.ip_block_batch_idx AND b.is_active = 1 AND ip.is_active = 1 AND (ip.expires_at IS NULL OR ip.expires_at > NOW())) AS effective_rule_count, (SELECT COUNT(*) FROM IP_BLOCKLIST ip WHERE ip.ip_block_batch_idx = b.ip_block_batch_idx AND ip.is_active = 1 AND ip.expires_at IS NOT NULL AND ip.expires_at <= NOW()) AS expired_rule_count FROM IP_BLOCK_BATCH b LEFT JOIN USERS cu ON cu.user_idx = b.created_by_user_idx LEFT JOIN USERS uu ON uu.user_idx = b.updated_by_user_idx WHERE 1=1
AND ( b.batch_code LIKE CONCAT('%', #{keyword}, '%') OR b.batch_name LIKE CONCAT('%', #{keyword}, '%') OR b.source_name LIKE CONCAT('%', #{keyword}, '%') OR b.description LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY b.is_active DESC, b.updated_at DESC, b.ip_block_batch_idx DESC LIMIT #{limit}

SELECT COUNT(*)
FROM USER_BLOCKLIST
WHERE user_idx = #{userIdx}
  AND is_active = 1
  AND block_target_key != #{excludeTargetKey}
